41	public class AutomationAPI extends ApiImplementor {
42	
43	    private static final Logger LOGGER = LogManager.getLogger(AutomationAPI.class);
44	
45	    private static final String PREFIX = "automation";
46	
47	    private static final String ACTION_RUN_PLAN = "runPlan";
48	    private static final String ACTION_END_DELAY_JOB = "endDelayJob";
49	    private static final String VIEW_PLAN_PROGRESS = "planProgress";
50	
51	    private static final String PARAM_FILE_PATH = "filePath";
52	    private static final String PARAM_PLAN_ID = "planId";
53	
54	    private static final String ELEMENT_INFO = "info";
55	    private static final String ELEMENT_WARN = "warn";
56	    private static final String ELEMENT_ERROR = "error";
57	
58	    private ExtensionAutomation extension;
59	
60	    /** Provided only for API client generator usage. */
61	    public AutomationAPI() {
62	        this(null);
63	    }
64	
65	    public AutomationAPI(ExtensionAutomation extension) {
66	        super();
67	        this.extension = extension;
68	        this.addApiAction(new ApiAction(ACTION_RUN_PLAN, new String[] {PARAM_FILE_PATH}));
69	        this.addApiAction(new ApiAction(ACTION_END_DELAY_JOB));
70	        this.addApiView(new ApiView(VIEW_PLAN_PROGRESS, new String[] {PARAM_PLAN_ID}));
71	    }
72	
73	    @Override
74	    public String getPrefix() {
75	        return PREFIX;
76	    }
77	
78	    @Override
79	    public ApiResponse handleApiAction(String name, JSONObject params) throws ApiException {
80	        LOGGER.debug("handleApiAction {} {}", name, params);
81	
82	        if (name.equals(ACTION_RUN_PLAN)) {
83	            try {
84	                AutomationPlan plan =
85	                        extension.loadPlan(
86	                                new File(ApiUtils.getNonEmptyStringParam(params, PARAM_FILE_PATH)));
87	                extension.registerPlan(plan);
88	
89	                if (View.isInitialised()) {
90	                    extension.displayPlan(plan);
91	                }
92	                extension.runPlanAsync(plan);
93	
94	                return new ApiResponseElement(PARAM_PLAN_ID, Integer.toString(plan.getId()));
95	            } catch (IOException | ApiException e) {
96	                throw new ApiException(Type.DOES_NOT_EXIST, e.getMessage());
97	            }
98	        } else if (name.equals(ACTION_END_DELAY_JOB)) {
99	            DelayJob.setEndJob(true);
100	            return ApiResponseElement.OK;
101	        }
102	        throw new ApiException(Type.BAD_ACTION);
103	    }
104	
105	    @Override
106	    public ApiResponse handleApiView(String name, JSONObject params) throws ApiException {
107	        LOGGER.debug("handleApiView {} {}", name, params);
108	
109	        if (name.equals(VIEW_PLAN_PROGRESS)) {
110	            AutomationPlan plan = extension.getPlan(params.getInt(PARAM_PLAN_ID));
111	
112	            if (plan == null) {
113	                throw new ApiException(Type.DOES_NOT_EXIST);
114	            }
115	
116	            return progressResponse(plan);
117	        }
118	        throw new ApiException(Type.BAD_VIEW);
119	    }
120	
121	    ApiResponse progressResponse(AutomationPlan plan) {
122	        HashMap<String, Object> map = new HashMap<>();
123	        map.put(PARAM_PLAN_ID, plan.getId());
124	
125	        if (plan.getStarted() != null) {
126	            map.put("started", plan.getStarted());
127	        }
128	        if (plan.getFinished() != null) {
129	            map.put("finished", plan.getFinished());
130	        }
131	
132	        ApiResponseList infoMsgs = new ApiResponseList(ELEMENT_INFO);
133	        plan.getProgress().getInfos().stream()
134	                .map(msg -> new ApiResponseElement(ELEMENT_INFO, msg))
135	                .forEach(infoMsgs::addItem);
136	        map.put(ELEMENT_INFO, infoMsgs);
137	
138	        ApiResponseList warnMsgs = new ApiResponseList(ELEMENT_WARN);
139	        plan.getProgress().getWarnings().stream()
140	                .map(msg -> new ApiResponseElement(ELEMENT_WARN, msg))
141	                .forEach(warnMsgs::addItem);
142	        map.put(ELEMENT_WARN, warnMsgs);
143	
144	        ApiResponseList errorMsgs = new ApiResponseList(ELEMENT_ERROR);
145	        plan.getProgress().getErrors().stream()
146	                .map(msg -> new ApiResponseElement(ELEMENT_ERROR, msg))
147	                .forEach(errorMsgs::addItem);
148	        map.put(ELEMENT_ERROR, errorMsgs);
149	
150	        return new ApiResponseSet<>(VIEW_PLAN_PROGRESS, map);
151	    }
152	}
